{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_882ec08e6ebd4ab68dbd4bc73f3ee369.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @if (submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@applicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <!-- Step Indicator Bar -->
        <div class="step-indicator">
            @for (int i = 0; i < stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCurrent = stepIndex == currentStep;
                var isCompleted = stepIndex < currentStep;
                var isFuture = stepIndex > currentStep;
                <div class="step-item @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                     @onclick="() => GoToStep(stepIndex)"
                     role="button"
                     tabindex="0">
                    <div class="step-circle">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@(stepIndex + 1)</span>
                        }
                    </div>
                    <div class="step-label">@stepNames[stepIndex]</div>
                </div>
                @if (stepIndex < stepNames.Length - 1)
                {
                    <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
                }
            }
        </div>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="alert alert-danger mt-3">@errorMessage</div>
        }

        <!-- Step 1: Personal Info -->
        @if (currentStep == 0)
        {
            <div class="step-content">
                <h3>Personal Information</h3>
                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="fullName" placeholder="Enter your full name" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="email" placeholder="you@example.com" />
                    @if (!string.IsNullOrEmpty(emailError))
                    {
                        <div class="text-danger mt-1">@emailError</div>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="phone" placeholder="(555) 123-4567" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <textarea class="form-control" @bind="address" rows="2" placeholder="Enter your address"></textarea>
                </div>
                <div class="step-buttons">
                    <div></div>
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                        @if (isValidating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span> <text>Validating…</text>
                        }
                        else
                        {
                            <text>Next →</text>
                        }
                    </button>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (currentStep == 1)
        {
            <div class="step-content">
                <h3>Work History</h3>
                @for (int i = 0; i < workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h5>Position @(index + 1)</h5>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="workEntries[index].Company" placeholder="Company name" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="workEntries[index].Title" placeholder="Job title" />
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" @bind="workEntries[index].StartDate" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="workEntries[index].EndDate"
                                       disabled="@workEntries[index].IsCurrent" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end mb-1">
                                <div class="form-check">
                                    <input class="form-check-input" type="checkbox" id="current-@index"
                                           @bind="workEntries[index].IsCurrent" />
                                    <label class="form-check-label" for="current-@index">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" @bind="workEntries[index].Description" rows="3"
                                      placeholder="Describe your responsibilities and achievements"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
                <div class="step-buttons">
                    <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next →</button>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (currentStep == 2)
        {
            <div class="step-content">
                <h3>References</h3>
                @for (int i = 0; i < references.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h5>Reference @(index + 1)</h5>
                            @if (references.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="references[index].Name" placeholder="Reference name" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="references[index].Relationship" placeholder="e.g., Former Manager" />
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" @bind="references[index].Email" placeholder="reference@example.com" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" @bind="references[index].Phone" placeholder="(555) 123-4567" />
                            </div>
                        </div>
                    </div>
                }
                @if (references.Count < 3)
                {
                    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
                }
                <div class="step-buttons">
                    <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next →</button>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (currentStep == 3)
        {
            <div class="step-content">
                <h3>Cover Letter</h3>
                <div class="mb-3">
                    <label class="form-label">Write your cover letter</label>
                    <textarea class="form-control cover-letter-textarea" @bind="coverLetter" @bind:event="oninput"
                              rows="12" maxlength="@maxCoverLetterLength"
                              placeholder="Tell us why you're a great fit for this position..."></textarea>
                    <div class="char-count @(coverLetter.Length > maxCoverLetterLength ? "text-danger" : "")">
                        @coverLetter.Length / @maxCoverLetterLength characters
                    </div>
                </div>
                <div class="step-buttons">
                    <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next →</button>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (currentStep == 4)
        {
            <div class="step-content">
                <h3>Review &amp; Submit</h3>

                <div class="review-section">
                    <div class="review-header">
                        <h5>Personal Information</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(0)'>Edit</button>
                    </div>
                    <dl class="review-dl">
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h5>Work History</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(1)'>Edit</button>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h5>References</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(2)'>Edit</button>
                    </div>
                    @foreach (var r in references)
                    {
                        <div class="review-work-entry">
                            <strong>@r.Name</strong> — @r.Relationship<br />
                            <span class="text-muted">@r.Email · @r.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h5>Cover Letter</h5>
                        <button class="btn btn-link btn-sm" @onclick='() => GoToStep(3)'>Edit</button>
                    </div>
                    <p class="review-cover-letter">@coverLetter</p>
                </div>

                <div class="step-buttons">
                    <button class="btn btn-secondary" @onclick="PreviousStep">← Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span> <text>Submitting…</text>
                        }
                        else
                        {
                            <text>Submit Application</text>
                        }
                    </button>
                </div>
            </div>
        }
    }
</div>

