toolArgs.file_text:
.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 1rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
    flex-wrap: wrap;
    gap: 0.25rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
    text-align: center;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step-item.current .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-label {
    margin-top: 0.35rem;
    font-size: 0.75rem;
    color: #adb5bd;
    white-space: nowrap;
}

.step-item.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    align-self: center;
    margin: 0 0.25rem;
    margin-bottom: 1.2rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Work Entry Cards */
.work-entry-card {
    border: 1px solid #e9ecef;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry-header h5 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    font-size: 0.95rem;
    line-height: 1.6;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Review & Submit */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h5 {
    margin: 0;
}

.review-dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-dl dt {
    color: #6c757d;
    font-weight: 500;
}

.review-dl dd {
    margin: 0;
}

.review-work-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.25rem;
    margin: 0;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #198754;
    color: #fff;
    font-size: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.application-id {
    font-size: 2rem;
    font-weight: 700;
    color: #0d6efd;
    margin: 1rem 0;
}

